  if (style.strokeWidth !== undefined) parts.push(`stroke-width="${escapeXml(style.strokeWidth)}"`);
  if (style.opacity !== undefined) parts.push(`opacity="${escapeXml(style.opacity)}"`);
  return parts.join(' ');
}

