  const lines = String(text).split('\n');
  const size = style.fontSize !== undefined ? Number(style.fontSize) : 14;
  const color = style.fontColor ?? '#000000';
  const tspans = lines
    .map((line, i) => `<tspan x="${cx}" dy="${i === 0 ? 0 : size * 1.2}">${escapeXml(line)}</tspan>`)
    .join('');
