    for (const env of envs) {
      if (ld.seen.has(env.id)) continue;
      ld.seen.add(env.id);
      fresh.push(env);
    }
    try {
      ld.doc.receive(fresh);
    } catch (err) {
      for (const env of fresh) ld.seen.delete(env.id);
      throw badRequest(err.message);
    }
    if (fresh.length) {
      ld.log.push(...fresh);
      store.appendOps(ld.meta.id, fresh);
