function connect() {
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  const ws = new WebSocket(`${proto}://${location.host}/ws/docs/${S.docId}?token=${encodeURIComponent(S.token)}`);
  S.ws = ws;
  ws.onopen = async () => {
    S.wsRetry = 0;
    setConn(true);
    try { await pullOps(); } catch { /* retried on next message */ }
    flush();
    refreshAll();
  };
  ws.onmessage = ev => onMessage(JSON.parse(ev.data));
  ws.onclose = () => {
    if (S.ws !== ws) return;
    setConn(false);
    S.inflight = 0;
    const delay = Math.min(10000, 500 * 2 ** S.wsRetry++);
    setTimeout(() => { if (S.ws === ws && S.docId) connect(); }, delay);
    S.ws = null;
  };
}

function disconnect() {
  const ws = S.ws;
  S.ws = null;
  S.docId = S.docId;
