  const mk = (actor) => {
    const d = { ...{ id: `e${suffix()}`, type: 'rect', x: 1, y: 2, width: 3, height: 4 } };
    return { id: `${actor}@1`, actor, lamport: 1, writes: [{ k: 'el', id: d.id, f: 'alive', v: true, t: [1, actor] }, { k: 'el', id: d.id, f: 'type', v: 'rect', t: [1, actor] }] };
