  const e1 = { id: 'x@1', actor: 'x', lamport: 1, writes: [{ k: 'el', id: 'q', f: 'alive', v: true, t: [1, 'x'] }, { k: 'el', id: 'q', f: 'type', v: 'rect', t: [1, 'x'] }] };
